import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long target = nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        Arrays.sort(a);
        int l = 0, r = n - 1;
        StringBuilder out = new StringBuilder();
        while (l < r) {
            long v = a[l] + a[r];
            if (v < target) l++;
            else if (v > target) r--;
            else {
                long low = a[l], high = a[r];
                out.append(low).append(',').append(high).append('\n');
                while (l < r && a[l] == low) l++;
                while (l < r && a[r] == high) r--;
            }
        }
        System.out.print(out.length() == 0 ? "None\n" : out.toString());
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	target := nextInt()
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	slices.Sort(a)
	l, r := 0, n-1
	var out []byte
	for l < r {
		v := a[l] + a[r]
		if v < target {
			l++
		} else if v > target {
			r--
		} else {
			low, high := a[l], a[r]
			out = strconv.AppendInt(out, low, 10)
			out = append(out, ',')
			out = strconv.AppendInt(out, high, 10)
			out = append(out, '\n')
			for l < r && a[l] == low {
				l++
			}
			for l < r && a[r] == high {
				r--
			}
		}
	}
	if len(out) == 0 {
		out = []byte("None\n")
	}
	os.Stdout.Write(out)
}
